        case 4:
          pOutCur--;
        *pOutCur = (uint8_t)uCodepoint & 0x3f | 0x80;
        uCodepoint >>= 6;
        case 3:
          pOutCur--;
        *pOutCur = (uint8_t)uCodepoint & 0x3f | 0x80;
